USE retail_sales_db;
    
DESCRIBE sales;
SELECT COUNT(*) AS total_rows
FROM retail_sales;

#1. Total Sales: Calculate the total sales revenue generated by the company.
SELECT
    SUM(Sales) AS Total_Sales
FROM retail_sales;

#2. Total Profit: Calculate the total profit earned by the company.
SELECT
    SUM(Profit) AS Total_Profit
FROM retail_sales;

#3. Region-Wise Sales: Calculate the total sales generated by each region and rank the regions from highest to lowest sales.
SELECT
    Region,
    SUM(Sales) AS Total_Sales
FROM retail_sales
GROUP BY Region
ORDER BY Total_Sales DESC;

#4. Category-Wise Profit: Calculate the total profit generated by each product category.
SELECT
    Category,
    SUM(Profit) AS Total_Profit
FROM retail_sales
GROUP BY Category
ORDER BY Total_Profit DESC;

#5. Top 5 Products: Identify the top 5 products that generated the highest sales revenue.
SELECT
    Product,
    SUM(Sales) AS Total_Sales
FROM retail_sales
GROUP BY Product
ORDER BY Total_Sales DESC
LIMIT 5;

#6. Classify each order into High, Medium, or Low Sales categories.
SELECT
    Order_ID,
    Product,
    Sales,
    CASE
        WHEN Sales >= 10000 THEN 'High Sales'
        WHEN Sales >= 5000 THEN 'Medium Sales'
        ELSE 'Low Sales'
    END AS Sales_Category
FROM retail_sales;

#7. Calculate Regional Sales Performance.
SELECT
    Region,
    CASE
        WHEN Sales >= 10000 THEN 'High Sales'
        WHEN Sales >= 5000 THEN 'Medium Sales'
        ELSE 'Low Sales'
    END AS Sales_Category,
    COUNT(*) AS Total_Orders
FROM retail_sales
GROUP BY
    Region,
    CASE
        WHEN Sales >= 10000 THEN 'High Sales'
        WHEN Sales >= 5000 THEN 'Medium Sales'
        ELSE 'Low Sales'
    END
ORDER BY Region, Total_Orders DESC;

#8. Find all orders whose sales value is greater than the average sales value of all orders.
SELECT
    Order_ID,
    Product,
    Region,
    Sales
FROM retail_sales
WHERE Sales > (
    SELECT AVG(Sales)
    FROM retail_sales
)
ORDER BY Sales DESC;

#9. Calculate Top 5 Highest-Sales Orders
SELECT
    Order_ID,
    Product,
    Region,
    Sales,
    Profit
FROM retail_sales
ORDER BY Sales DESC
LIMIT 5;

#10. Identify all orders whose sales value is greater than the average sales value of their respective region.
SELECT
    rs.Order_ID,
    rs.Region,
    rs.Product,
    rs.Sales
FROM retail_sales AS rs
WHERE rs.Sales > (
    SELECT AVG(rs2.Sales)
    FROM retail_sales AS rs2
    WHERE rs2.Region = rs.Region
);

#11. Find Top3 Order of Every Region.
WITH RankedOrders AS (
    SELECT
        Order_ID,
        Region,
        Product,
        Sales,
        ROW_NUMBER() OVER (
            PARTITION BY Region
            ORDER BY Sales DESC
        ) AS order_rank
    FROM retail_sales
)
SELECT *
FROM RankedOrders
WHERE order_rank <= 3
ORDER BY Region, order_rank;

#12. calculate the cumulative sales over time to track sales growth?
SELECT
    Order_Date,
    Order_ID,
    Sales,
    SUM(Sales) OVER (
        ORDER BY Order_Date, Order_ID
        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
    ) AS Running_Total_Sales
FROM retail_sales
ORDER BY Order_Date, Order_ID;
